126: // Returns 0 if successful
127: // Returns -1 if unsuccessful
128: static int init_header_info(twolame_options * glopts)
129: {
130:     frame_header *header = &glopts->header;
131: 
132:     /* use the options to create header info structure */
133:     header->lay = 2;
134:     header->error_protection = glopts->error_protection;
135:     header->version = glopts->version;
136: 
137:     // Convert the sampling frequency to the required index
138:     header->samplerate_idx = twolame_get_samplerate_index(glopts->samplerate_out);
139:     if (header->samplerate_idx < 0) {
140:         fprintf(stderr, "Not a valid samplerate: %i\n", glopts->samplerate_out);
141:         return -1;
142:     }
143: 
144:     // Convert the bitrate to the an index
145:     if (glopts->freeformat)
146:         header->bitrate_index = 0;
147:     else
148:     {
149:         header->bitrate_index = twolame_get_bitrate_index(glopts->bitrate, header->version);
150:         if (header->bitrate_index < 0) {
151:             fprintf(stderr, "Not a valid bitrate (%i) for MPEG version '%s'\n", glopts->bitrate,
152:                     twolame_mpeg_version_name(glopts->version));
153:             return -1;
154:         }
155:     }
156:     if (glopts->vbr && glopts->vbr_max_bitrate > 0)
157:     {
158:         /* user required vbr and a specified max bitrate */
159:         /* convert max VBR bitrate to an index */
160:         glopts->vbr_upper_index = twolame_get_bitrate_index(glopts->vbr_max_bitrate, header->version);
161:         if (glopts->vbr_upper_index < 0) {
162:             fprintf(stderr, "Not a valid max VBR bitrate for this version: %i\n",
163:                     glopts->vbr_max_bitrate);
164:             return -1;
165:         }
166:     }
167:     // Copy across the other settings
168:     header->padding = 0; /* when requested, padding will be evaluated later for this frame */
169:     header->private_extension = glopts->private_extension;
170:     header->mode = glopts->mode;
171:     header->mode_ext = 0;
172:     header->copyright = glopts->copyright;
173:     header->original = glopts->original;
174:     header->emphasis = glopts->emphasis;
175: 
176:     return 0;
177: }
