182: /**
183:  * This function should actually *check* the parameters to see if they
184:  * make sense.
185:  */
186: 
187: int twolame_init_params(twolame_options * glopts)
188: {
189: 
190:     if (glopts->twolame_init) {
191:         fprintf(stderr, "Already called twolame_init_params() once.\n");
192:         return 1;
193:     }
194:     // Check the number of channels
195:     if (glopts->num_channels_in != 1 && glopts->num_channels_in != 2) {
196:         if (glopts->num_channels_in == 0) {
197:             /* this error is due to the caller frontend */
198:             fprintf(stderr,
199:                     "twolame_init_params(): must specify number of input channels using twolame_set_num_channels().\n");
200:         }
201:         else {
202:             /* this error is due to the user feeding a wrong file */
203:             fprintf(stderr,
204:                     "Error: twolame cannot encode files with more than 2 channels.\n");
205:         }
206:         return -1;
207:     }
208:     // If not output samplerate has been set, then set it to the input sample rate
209:     if (glopts->samplerate_out < 1) {
210:         glopts->samplerate_out = glopts->samplerate_in;
211:     }
212:     // If the MPEG version has not been set, then choose automatically
213:     if (glopts->version == -1) {
214:         // Get the MPEG version for the chosen samplerate
215:         glopts->version = twolame_get_version_for_samplerate(glopts->samplerate_out);
216:         if (glopts->version < 0) {
217:             fprintf(stderr, "twolame_init_params(): invalid samplerate: %i\n",
218:                     glopts->samplerate_out);
219:             return -1;
220:         } else if (glopts->verbosity >= 3) {
221:             fprintf(stderr, "Chosen version '%s' for samplerate of %d Hz.\n",
222:                     twolame_mpeg_version_name(glopts->version), glopts->samplerate_out);
223:         }
224:     }
225:     // Choose mode (if none chosen)
226:     if (glopts->mode == TWOLAME_AUTO_MODE) {
227:         if (glopts->num_channels_in == 2)
228:             glopts->mode = TWOLAME_STEREO;
229:         else
230:             glopts->mode = TWOLAME_MONO;
231:         if (glopts->verbosity >= 3) {
232:             fprintf(stderr, "Chosen mode to be '%s' because of %d input channels.\n",
233:                     twolame_get_mode_name(glopts), glopts->num_channels_in);
234:         }
235:     }
236:     // Choose the bitrate (if none chosen)
237:     if (glopts->bitrate < 0 && !glopts->vbr) {
238:         if (glopts->mode == TWOLAME_MONO) {
239:             switch (glopts->samplerate_out) {
240:             case 48000:
241:                 glopts->bitrate = 96;
242:                 break;          // (LAME=64)
243:             case 44100:
244:                 glopts->bitrate = 96;
245:                 break;          // (LAME=64)
246:             case 32000:
247:                 glopts->bitrate = 80;
248:                 break;          // (LAME=48)
249:             case 24000:
250:                 glopts->bitrate = 48;
251:                 break;          // (LAME=32)
252:             case 22050:
253:                 glopts->bitrate = 48;
254:                 break;          // (LAME=32)
255:             case 16000:
256:                 glopts->bitrate = 32;
257:                 break;          // (LAME=24)
258:             }
259:         } else {
260:             switch (glopts->samplerate_out) {
261:             case 48000:
262:                 glopts->bitrate = 192;
263:                 break;          // (LAME=128)
264:             case 44100:
265:                 glopts->bitrate = 192;
266:                 break;          // (LAME=128)
267:             case 32000:
268:                 glopts->bitrate = 160;
269:                 break;          // (LAME=96)
270:             case 24000:
271:                 glopts->bitrate = 96;
272:                 break;          // (LAME=64)
273:             case 22050:
274:                 glopts->bitrate = 96;
275:                 break;          // (LAME=64)
276:             case 16000:
277:                 glopts->bitrate = 64;
278:                 break;          // (LAME=48)
279:             }
280:         }
281:         if (glopts->verbosity >= 3) {
282:             fprintf(stderr, "Chosen bitrate of %dkbps for samplerate of %d Hz.\n",
283:                     glopts->bitrate, glopts->samplerate_out);
284:         }
285:         glopts->freeformat = FALSE;   // no sense in requiring freeformat encoding without setting a bitrate
286:     }
287:     if (glopts->bitrate < 0 && glopts->vbr) {
288:         /* set the minimum bitrate - 'init_bit_allocation' will fix it if needed */
289:         glopts->bitrate = twolame_index_bitrate((int)glopts->version, 1);
290:     }
291: 
292:     /* Check for bitrate validity */
293:     if (glopts->version == TWOLAME_MPEG1
294:             &&
295:             !glopts->freeformat
296:             &&
297:             !glopts->vbr) {
298:         /* some limitation apply for MPEG1 when CBR and freeformat is not selected */
299:         if (glopts->mode == TWOLAME_MONO) {
300:             if (glopts->bitrate > 192) {
301:                 fprintf(stderr, "twolame_init_params(): %dkbps is an invalid bitrate for mono encoding.\n",
302:                         glopts->bitrate);
303:                 return -1;
304:             }
305:         }
306:         else {
307:             if (glopts->bitrate < 64 || glopts->bitrate == 80) {
308:                 fprintf(stderr, "twolame_init_params(): %dkbps is an invalid bitrate for 2ch encoding.\n",
309:                         glopts->bitrate);
310:                 return -1;
311:             }
312:         }
313:     }
314: 
315:     /* Can't do DAB and energylevel extensions at the same time Because both of them think they're
316:        the only ones inserting information into the ancillary section of the frame */
317:     if (glopts->do_dab && glopts->do_energy_levels) {
318:         fprintf(stderr, "Error: Can't do DAB and Energy Levels at the same time\n");
319:         return -1;
320:     }
321: 
322:     /* Set the number of ancillary bits automatically, if none set */
323:     if (glopts->num_ancillary_bits < 0) {
324:         if (glopts->do_energy_levels) {
325:             glopts->num_ancillary_bits = twolame_get_required_energy_bits(glopts);
326:         } else {
327:             glopts->num_ancillary_bits = 0;
328:         }
329:     }
330: 
331:     /* Check that if we're doing energy levels, that there's enough space to put the information */
332:     if (glopts->do_energy_levels) {
333:         int required = twolame_get_required_energy_bits(glopts);
334:         if (glopts->num_ancillary_bits < required) {
335:             fprintf(stderr, "Warning: Too few ancillary bits to store energy levels: %i<%i\n",
336:                     glopts->num_ancillary_bits, required);
337:             return -1;
338:         }
339:     }
340: 
341:     /*
342:      * MFC Feb 2003: in VBR mode, joint
343:      * stereo doesn't make any sense at
344:      * the moment, as there are no noisy
345:      * subbands according to
346:      * bits_for_nonoise in vbr mode
347:      */
348:     if (glopts->vbr && glopts->mode == TWOLAME_JOINT_STEREO) {
349:         fprintf(stderr, "Warning: Can't do Joint Stereo with VBR, switching to normal stereo.\n");
350: 
351:         // force stereo mode
352:         twolame_set_mode(glopts, TWOLAME_STEREO);
353:     }
354: 
355:     /* Can't do padding and VBR at same time */
356:     if (glopts->vbr && glopts->padding == TRUE) {
357:         fprintf(stderr, "Error: Can't do padding and VBR at same time\n");
358:         return -1;
359:     }
360: 
361:     /* Simple patch for the `bit_stream buffer needs to be bigger' warning */
362:     /* Fix FREEFORMAT_MAX_BITRATE definition when github issue #51 will be closed */
363:     if (glopts->freeformat && glopts->bitrate > FREEFORMAT_MAX_BITRATE) {
364:         fprintf(stderr, "twolame_init_params(): cannot encode freeformat stream at %d kbps\n", glopts->bitrate);
365:         return -1;
366:     }
367: 
368:     // Set the Number of output channels
369:     glopts->num_channels_out = (glopts->mode == TWOLAME_MONO) ? 1 : 2;
370: 
371: 
372: 
373:     // build mpeg header from parameters
374:     if (init_header_info(glopts) < 0) {
375:         return -1;
376:     }
377:     // initialise bitrate allocation
378:     if (twolame_init_bit_allocation(glopts) < 0) {
379:         return -1;
380:     }
381:     // Select table number and sblimit
382:     if (twolame_encode_init(glopts) < 0) {
383:         return -1;
384:     }
385:     // Check input samplerate is same as output samplerate
386:     if (glopts->samplerate_out != glopts->samplerate_in) {
387:         fprintf(stderr,
388:                 "twolame_init_params(): sorry, twolame doesn't support resampling (yet).\n");
389:         return -1;
390:     }
391: 
392:     // Initialise internal variables
393:     glopts->samples_in_buffer = 0;
394:     glopts->psycount = 0;
395: 
396: 
397:     // Allocate memory to larger buffers
398:     glopts->subband = (subband_t *) TWOLAME_MALLOC(sizeof(subband_t));
399:     glopts->j_sample = (jsb_sample_t *) TWOLAME_MALLOC(sizeof(jsb_sample_t));
400:     glopts->sb_sample = (sb_sample_t *) TWOLAME_MALLOC(sizeof(sb_sample_t));
401:     if (glopts->subband == NULL
402:             ||
403:             glopts->j_sample == NULL
404:             ||
405:             glopts->sb_sample == NULL)
406:     {
407:         TWOLAME_FREE(glopts->subband);
408:         TWOLAME_FREE(glopts->j_sample);
409:         TWOLAME_FREE(glopts->sb_sample);
410:         return -1;
411:     }
412: 
413:     // clear buffers
414:     memset((char *) glopts->buffer, 0, sizeof(glopts->buffer));
415:     memset((char *) glopts->bit_alloc, 0, sizeof(glopts->bit_alloc));
416:     memset((char *) glopts->scfsi, 0, sizeof(glopts->scfsi));
417:     memset((char *) glopts->scalar, 0, sizeof(glopts->scalar));
418:     memset((char *) glopts->j_scale, 0, sizeof(glopts->j_scale));
419:     memset((char *) glopts->smrdef, 0, sizeof(glopts->smrdef));
420:     memset((char *) glopts->smr, 0, sizeof(glopts->smr));
421:     memset((char *) glopts->max_sc, 0, sizeof(glopts->max_sc));
422: 
423:     // Initialise subband windowfilter
424:     if (twolame_init_subband(&glopts->smem) < 0) {
425:         return -1;
426:     }
427:     // All initialised now :)
428:     glopts->twolame_init++;
429: 
430:     return (0);
431: }
