482: /*
483:     Encode a single frame of audio from 1152 samples
484:     Audio samples are taken from glopts->buffer
485:     Encoded bit stream is placed in to parameter bs
486:     (not intended for use outside the library)
487: 
488:     Returns the size of the frame
489:     or -1 if there is an error
490: */
491: static int encode_frame(twolame_options * glopts, bit_stream * bs)
492: {
493:     int nch = glopts->num_channels_out;
494:     int sb, ch, adb, i;
495:     unsigned long frameBits, initial_bits;
496:     short sam[2][1056];
497: 
498:     if (!glopts->twolame_init) {
499:         fprintf(stderr, "Please call twolame_init_params() before starting encoding.\n");
500:         return -1;
501:     }
502:     // Scale and mix the input buffer
503:     scale_and_mix_samples(glopts);
504: 
505: 
506:     // Clear the saved audio buffer
507:     memset((char *) sam, 0, sizeof(sam));
508: 
509:     // Number of bits to calculate CRC on
510:     glopts->num_crc_bits = 0;
511: 
512:     // Store the number of bits initially in the bit buffer
513:     initial_bits = twolame_buffer_sstell(bs);
514: 
515:     adb = twolame_available_bits(glopts);
516: 
517:     /* allow the user to reserve some space at the end of the frame This will however leave fewer
518:        bits for the audio. Need to do a sanity check here to see that there are *some* bits left. */
519:     if (glopts->num_ancillary_bits > 0.6 * adb) {
520:         /* Trying to reserve more than 60% of the frame. 0.6 is arbitrary. but since most
521:            applications probably only want to reserve a few bytes, this seems fine. Typical frame
522:            size is about 800bytes */
523:         fprintf(stderr,
524:                 "You're trying to reserve more than 60%% of the mpeg frame for ancillary data\n");
525:         fprintf(stderr, "This is probably an error. But I'll keep going anyway...\n");
526:     }
527: 
528:     adb -= glopts->num_ancillary_bits;
529: 
530: 
531:     /* The DAB scf-crc calc is done below. The frontend will have to keep the previous frame in
532:        memory. As of 09May 2014 all that needs to be done is for the frontend to buffer one frame in
533:        memory and call twolame_set_DAB_scf_crc */
534: 
535:     {
536:         int gr, bl, ch;
537:         /* New polyphase filter Combines windowing and filtering. Ricardo Feb'03 */
538:         for (gr = 0; gr < 3; gr++)
539:             for (bl = 0; bl < 12; bl++)
540:                 for (ch = 0; ch < nch; ch++)
541:                     twolame_window_filter_subband(&glopts->smem,
542:                                                   &glopts->buffer[ch][gr * 12 * 32 + 32 * bl], ch,
543:                                                   &(*glopts->sb_sample)[ch][gr][bl][0]);
544:     }
545: 
546:     twolame_scalefactor_calc(*glopts->sb_sample, glopts->scalar, nch, glopts->sblimit);
547:     twolame_find_sf_max(glopts, glopts->scalar, glopts->max_sc);
548:     if (glopts->mode == TWOLAME_JOINT_STEREO) {
549:         // this way we calculate more mono than we need but it is cheap
550:         twolame_combine_lr(*glopts->sb_sample, *glopts->j_sample, glopts->sblimit);
551:         twolame_scalefactor_calc(glopts->j_sample, &glopts->j_scale, 1, glopts->sblimit);
552:     }
553: 
554:     if ((glopts->quickmode == TRUE) && (++glopts->psycount % glopts->quickcount != 0)) {
555:         /* We're using quick mode, so we're only calculating the model every 'quickcount' frames.
556:            Otherwise, just copy the old ones across */
557:         for (ch = 0; ch < nch; ch++) {
558:             for (sb = 0; sb < SBLIMIT; sb++) {
559:                 glopts->smr[ch][sb] = glopts->smrdef[ch][sb];
560:             }
561:         }
562:     } else {
563:         // calculate the psymodel
564:         switch (glopts->psymodel) {
565:         case -1:
566:             twolame_psycho_n1(glopts, glopts->smr, nch);
567:             break;
568:         case 0:                // Psy Model A
569:             twolame_psycho_0(glopts, glopts->smr, glopts->scalar);
570:             break;
571:         case 1:
572:             twolame_psycho_1(glopts, glopts->buffer, glopts->max_sc, glopts->smr);
573:             break;
574:         case 2:
575:             twolame_psycho_2(glopts, glopts->buffer, sam, glopts->smr);
576:             break;
577:         case 3:
578:             // Modified psy model 1
579:             twolame_psycho_3(glopts, glopts->buffer, glopts->max_sc, glopts->smr);
580:             break;
581:         case 4:
582:             // Modified psy model 2
583:             twolame_psycho_4(glopts, glopts->buffer, sam, glopts->smr);
584:             break;
585:         default:
586:             fprintf(stderr, "Invalid psy model specification: %i\n", glopts->psymodel);
587:             return -1;
588:             break;
589:         }
590: 
591:         if (glopts->quickmode == TRUE) {
592:             // copy the smr values and reuse them later
593:             for (ch = 0; ch < nch; ch++) {
594:                 for (sb = 0; sb < SBLIMIT; sb++)
595:                     glopts->smrdef[ch][sb] = glopts->smr[ch][sb];
596:             }
597:         }
598:     }
599: 
600: 
601:     twolame_sf_transmission_pattern(glopts, glopts->scalar, glopts->scfsi);
602:     twolame_main_bit_allocation(glopts, glopts->smr, glopts->scfsi, glopts->bit_alloc, &adb);
603: 
604:     twolame_write_header(glopts, bs);
605: 
606:     // Leave space for 2 bytes of CRC to be filled in later
607:     if (glopts->error_protection)
608:         buffer_putbits(bs, 0, 16);
609: 
610:     twolame_write_bit_alloc(glopts, glopts->bit_alloc, bs);
611:     twolame_write_scalefactors(glopts, glopts->bit_alloc, glopts->scfsi, glopts->scalar, bs);
612: 
613:     twolame_subband_quantization(glopts, glopts->scalar, *glopts->sb_sample, glopts->j_scale,
614:                                  *glopts->j_sample, glopts->bit_alloc, *glopts->subband);
615:     twolame_write_samples(glopts, *glopts->subband, glopts->bit_alloc, bs);
616: 
617:     // If not all the bits were used, write out a stack of zeros
618:     for (i = 0; i < adb; i++)
619:         buffer_put1bit(bs, 0);
620: 
621: 
622:     /* pad the current frame when needed */
623:     if (glopts->header.padding)
624:         // input file
625:         buffer_putbits(bs, 0, 8);
626: 
627:     if (glopts->do_dab) {
628:         // Do the CRC calc for DAB stuff if required.
629:         // It will be up to the frontend to insert it into the end of the
630:         // previous frame.
631:         for (i = glopts->dab_crc_len - 1; i >= 0; i--) {
632:             twolame_dab_crc_calc(glopts, glopts->bit_alloc, glopts->scfsi, glopts->scalar,
633:                                  &glopts->dab_crc[i], i);
634:         }
635:     }
636:     // Allocate space for the reserved ancillary bits
637:     for (i = 0; i < glopts->num_ancillary_bits; i++)
638:         buffer_put1bit(bs, 0);
639: 
640: 
641:     // Calculate the number of bits in this frame
642:     frameBits = twolame_buffer_sstell(bs) - initial_bits;
643:     if (frameBits % 8) {        /* a program failure */
644:         fprintf(stderr, "Sent %ld bits = %ld slots plus %ld\n", frameBits, frameBits / 8,
645:                 frameBits % 8);
646:         fprintf(stderr, "If you are reading this, the program is broken\n");
647:         fprintf(stderr, "email %s with the command line arguments and other info\n",
648:                 PACKAGE_BUGREPORT);
649:         return -1;
650:     }
651:     // Store the energy levels at the end of the frame
652:     if (glopts->do_energy_levels)
653:         twolame_do_energy_levels(glopts, bs);
654: 
655:     // MEANX: Recompute checksum from bitstream
656:     if (glopts->error_protection) {
657:         unsigned char *frame_ptr = bs->buf + (initial_bits >> 3);
658:         twolame_crc_writeheader(frame_ptr, glopts->num_crc_bits);
659:     }
660:     // fprintf(stderr,"Frame size: %li\n\n",frameBits/8);
661: 
662:     return frameBits / 8;
663: }
