645: /*
646:   format_duration_string()
647:   Create human readable duration string from libsndfile info
648: */
649: static char *format_duration_string(SF_INFO * sfinfo, char *string, int string_size)
650: {
651:     float seconds = 0.0f;
652:     int minutes = 0;
653: 
654:     if (sfinfo->frames == 0 || sfinfo->samplerate == 0) {
655:         snprintf(string, string_size, "Unknown");
656:     } else {
657: 
658:         // Calculate the number of minutes and seconds
659:         seconds = sfinfo->frames / sfinfo->samplerate;
660:         minutes = (seconds / 60);
661:         seconds -= (minutes * 60);
662: 
663:         // Create a string out of it
664:         snprintf(string, string_size, "%imin %1.1fsec", minutes, seconds);
665:     }
666:     return string;
667: }
