469:         glopts->dab_crc_len = 4;
470:     }
471:     else if (glopts->mode == TWOLAME_MONO) {
472:         if (glopts->bitrate >= 56)
473:             glopts->dab_crc_len = 4;
474:         else
475:             glopts->dab_crc_len = 2;
476:     }
477:     else if (glopts->bitrate >= 112)
478:         glopts->dab_crc_len = 4;
479:     else
480:         glopts->dab_crc_len = 2;
481:     return (0);
