{
    return (glopts->scale);
}

int twolame_set_scale_left(twolame_options * glopts, float scale)
{
    if (scale < 0) {
        fprintf(stderr, "invalid scaling amount %f\n", scale);
        return (-1);
    }
    glopts->scale_left = scale;
    return 0;
}

float twolame_get_scale_left(twolame_options * glopts)
{
